const NV="2026-03-11",OWNERS="391534e1-09e6-8134-908a-000b92c0ac22";
const PDF="";
async function notion(path,token,opt={}){return fetch("https://api.notion.com/v1"+path,{...opt,headers:{Authorization:"Bearer "+token,"Notion-Version":NV,"Content-Type":"application/json"}})}
async function trash(id,token){if(id)await notion("/pages/"+id,token,{method:"PATCH",body:JSON.stringify({in_trash:true})})}
export default async function handler(req,res){
  res.setHeader("Cache-Control","no-store");const token=process.env.NOTION_TOKEN;if(!token)return res.status(500).json({ok:false});
  const email="contact@casaperpi.com";
  const q=await notion("/data_sources/"+OWNERS+"/query",token,{method:"POST",body:JSON.stringify({filter:{property:"Email",email:{equals:email}},page_size:1})});
  const qd=await q.json();if(qd.results?.length)return res.status(409).json({ok:false,error:"test_email_conflict"});
  const stamp=Date.now(),host=req.headers.host,payload={"Nom et prénom":"TEST PDF CASA PERPI","Téléphone":"0600000000",email,"Adresse exacte du logement":"TEST PDF — "+stamp,"Capacité voyageurs":"2","Canaux utilisés":["Direct"],Dossier:"TEST-PDF-"+stamp};
  const body={payload,bookings:[],pdf:{name:"TEST_Casa_Perpi.pdf",base64:PDF},honey:""};
  const r=await fetch("https://"+host+"/api/onboarding",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),data=await r.json().catch(()=>({}));
  if(!r.ok||!data.ok)return res.status(500).json({ok:false,error:"pipeline_failed",detail:data});
  const ids=[...(data.reservationIds||[]),data.documentId,data.onboardingId,data.propertyId,data.ownerId].filter(Boolean);for(const id of ids)await trash(id,token);
  return res.status(200).json({ok:true,pdfUpload:true,resendAttachment:true,cleanup:true});
}
